// ---------------------------------------------------------------------------
// Vertex / constant-buffer layouts
// ---------------------------------------------------------------------------
struct alignas(16) CBOverlay
{
    float screenW;
    float screenH;
    float pad0;
    float pad1;
};

struct Vertex2D
{
    float x, y;        // NDC
    float u, v;        // font UV
    float r, g, b, a; // colour
};

// ---------------------------------------------------------------------------
// HLSL shaders (compiled at runtime with D3DCompile)
// ---------------------------------------------------------------------------
static const char kVS[] = R"hlsl(
cbuffer CBOverlay : register(b0)
{
    float screenW;
    float screenH;
    float pad0;
    float pad1;
};

struct VSIn  { float2 pos : POSITION; float2 uv : TEXCOORD; float4 col : COLOR; };
struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD; float4 col : COLOR; };

VSOut main(VSIn v)
{
    VSOut o;
    // pixel coords -> NDC
    float2 ndc = float2(v.pos.x / screenW * 2.0f - 1.0f,
                        1.0f - v.pos.y / screenH * 2.0f);
    o.pos = float4(ndc, 0.0f, 1.0f);
    o.uv  = v.uv;
    o.col = v.col;
    return o;
}
)hlsl";

static const char kPS[] = R"hlsl(
Texture2D    fontTex : register(t0);
SamplerState fontSmp : register(s0);

struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD; float4 col : COLOR; };

float4 main(VSOut i) : SV_TARGET
{
    float alpha = fontTex.Sample(fontSmp, i.uv).r;
    return float4(i.col.rgb, i.col.a * alpha);
}
)hlsl";

// ---------------------------------------------------------------------------
// Overlay renderer
// ---------------------------------------------------------------------------
class DebugOverlay
{
public:
    DebugOverlay() = default;
    ~DebugOverlay() { destroy(); }

    bool init(HWND hwnd);
    void beginFrame();
    void drawText(float px, float py, const char* text,
                  float r, float g, float b, float a = 1.0f);
    void drawEntityMarker(float px, float py,
                          float r, float g, float b);
    void endFrame();
    void destroy();

    UINT  width()  const { return m_width; }
    UINT  height() const { return m_height; }

private:
    // helpers
    void  pushGlyph(float px, float py, uint8_t ch,
                    float r, float g, float b, float a);
    void  flushVB();
    bool  compileShader(const char* src, const char* entry,
                        const char* model, ID3DBlob** ppBlob);

    // D3D objects
    ID3D11Device*           m_dev  = nullptr;
    ID3D11DeviceContext*    m_ctx  = nullptr;
    IDXGISwapChain*         m_sc   = nullptr;
    ID3D11RenderTargetView* m_rtv  = nullptr;
    ID3D11Buffer*           m_vb   = nullptr;
    ID3D11Buffer*           m_cb   = nullptr;
    ID3D11InputLayout*      m_il   = nullptr;
    ID3D11VertexShader*     m_vs   = nullptr;
    ID3D11PixelShader*      m_ps   = nullptr;
    ID3D11Texture2D*        m_fontTex  = nullptr;
    ID3D11ShaderResourceView* m_fontSrv = nullptr;
    ID3D11SamplerState*     m_fontSmp  = nullptr;
    ID3D11BlendState*       m_blend    = nullptr;
    ID3D11RasterizerState*  m_rast     = nullptr;
    ID3D11DepthStencilState* m_dss     = nullptr;

    static constexpr UINT kMaxVerts = 65536;
    std::vector<Vertex2D> m_verts;

    UINT m_width  = 0;
    UINT m_height = 0;
};

// ---------------------------------------------------------------------------
bool DebugOverlay::compileShader(const char* src, const char* entry,
                                 const char* model, ID3DBlob** ppBlob)
{
    ID3DBlob* errBlob = nullptr;
    HRESULT hr = D3DCompile(src, strlen(src), nullptr, nullptr, nullptr,
                            entry, model,
                            D3DCOMPILE_ENABLE_STRICTNESS, 0,
                            ppBlob, &errBlob);
    if (FAILED(hr))
    {
        if (errBlob)
        {
            OutputDebugStringA(
                static_cast<const char*>(errBlob->GetBufferPointer()));
            errBlob->Release();
        }
        return false;
    }
    if (errBlob) errBlob->Release();
    return true;
}

bool DebugOverlay::init(HWND hwnd)
{
    RECT rc{};
    GetClientRect(hwnd, &rc);
    m_width  = static_cast<UINT>(rc.right  - rc.left);
    m_height = static_cast<UINT>(rc.bottom - rc.top);

    // --- swap chain + device ---
    DXGI_SWAP_CHAIN_DESC scd{};
    scd.BufferCount                        = 2;
    scd.BufferDesc.Width                   = m_width;
    scd.BufferDesc.Height                  = m_height;
    scd.BufferDesc.Format                  = DXGI_FORMAT_R8G8B8A8_UNORM;
    scd.BufferDesc.RefreshRate.Numerator   = 60;
    scd.BufferDesc.RefreshRate.Denominator = 1;
    scd.BufferUsage                        = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    scd.OutputWindow                       = hwnd;
    scd.SampleDesc.Count                   = 1;
    scd.Windowed                           = TRUE;
    scd.SwapEffect                         = DXGI_SWAP_EFFECT_DISCARD;

    UINT flags = 0;
#ifdef _DEBUG
    flags |= D3D11_CREATE_DEVICE_DEBUG;
#endif

    D3D_FEATURE_LEVEL featureLevel = D3D_FEATURE_LEVEL_11_0;
    HRESULT hr = D3D11CreateDeviceAndSwapChain(
        nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr,
        flags, &featureLevel, 1,
        D3D11_SDK_VERSION,
        &scd, &m_sc,
        &m_dev, nullptr, &m_ctx);
    if (FAILED(hr)) return false;

    // --- RTV ---
    {
        ID3D11Texture2D* back = nullptr;
        m_sc->GetBuffer(0, __uuidof(ID3D11Texture2D),
                        reinterpret_cast<void**>(&back));
        m_dev->CreateRenderTargetView(back, nullptr, &m_rtv);
        back->Release();
    }

    // --- vertex buffer ---
    {
        D3D11_BUFFER_DESC bd{};
        bd.ByteWidth      = sizeof(Vertex2D) * kMaxVerts;
        bd.Usage          = D3D11_USAGE_DYNAMIC;
        bd.BindFlags      = D3D11_BIND_VERTEX_BUFFER;
        bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        if (FAILED(m_dev->CreateBuffer(&bd, nullptr, &m_vb)))
            return false;
    }

    // --- constant buffer ---
    {
        D3D11_BUFFER_DESC bd{};
        bd.ByteWidth      = sizeof(CBOverlay);
        bd.Usage          = D3D11_USAGE_DYNAMIC;
        bd.BindFlags      = D3D11_BIND_CONSTANT_BUFFER;
        bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        if (FAILED(m_dev->CreateBuffer(&bd, nullptr, &m_cb)))
            return false;
    }

    // --- shaders + input layout ---
    {
        ID3DBlob* vsBlob = nullptr;
        ID3DBlob* psBlob = nullptr;
        if (!compileShader(kVS, "main", "vs_5_0", &vsBlob)) return false;
        if (!compileShader(kPS, "main", "ps_5_0", &psBlob)) { vsBlob->Release(); return false; }

        m_dev->CreateVertexShader(vsBlob->GetBufferPointer(),
                                  vsBlob->GetBufferSize(), nullptr, &m_vs);
        m_dev->CreatePixelShader(psBlob->GetBufferPointer(),
                                 psBlob->GetBufferSize(), nullptr, &m_ps);

        D3D11_INPUT_ELEMENT_DESC ied[] =
        {
            {"POSITION", 0, DXGI_FORMAT_R32G32_FLOAT,    0,  0, D3D11_INPUT_PER_VERTEX_DATA, 0},
            {"TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT,    0,  8, D3D11_INPUT_PER_VERTEX_DATA, 0},
            {"COLOR",    0, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, 16, D3D11_INPUT_PER_VERTEX_DATA, 0},
        };
        m_dev->CreateInputLayout(ied, 3,
                                 vsBlob->GetBufferPointer(),
                                 vsBlob->GetBufferSize(), &m_il);
        vsBlob->Release();
        psBlob->Release();
    }

    // --- font texture: 128×8, one row per char, one bit per pixel -> R8 ---
    {
        // 128 chars × 8 columns × 8 rows = 8192 texels arranged as 1024×8
        constexpr int COLS = 128; // characters wide
        constexpr int W    = COLS * 8;
        constexpr int H    = 8;
        static uint8_t texData[H * W] = {};
        for (int ch = 0; ch < 128; ch++)
        {
            for (int row = 0; row < 8; row++)
            {
                uint8_t bits = kFont8x8[ch][row];
                for (int col = 0; col < 8; col++)
                {
                    int texX = ch * 8 + col;
                    int texY = row;
                    texData[texY * W + texX] =
                        (bits & (0x80u >> col)) ? 0xFF : 0x00;
                }
            }
        }

        D3D11_TEXTURE2D_DESC td{};
        td.Width              = W;
        td.Height             = H;
        td.MipLevels          = 1;
        td.ArraySize          = 1;
        td.Format             = DXGI_FORMAT_R8_UNORM;
        td.SampleDesc.Count   = 1;
        td.Usage              = D3D11_USAGE_IMMUTABLE;
        td.BindFlags          = D3D11_BIND_SHADER_RESOURCE;

        D3D11_SUBRESOURCE_DATA init{};
        init.pSysMem     = texData;
        init.SysMemPitch = W;
        if (FAILED(m_dev->CreateTexture2D(&td, &init, &m_fontTex)))
            return false;
        if (FAILED(m_dev->CreateShaderResourceView(m_fontTex, nullptr, &m_fontSrv)))
            return false;
    }

    // --- sampler ---
    {
        D3D11_SAMPLER_DESC sd{};
        sd.Filter         = D3D11_FILTER_MIN_MAG_MIP_POINT;
        sd.AddressU       = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.AddressV       = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.AddressW       = D3D11_TEXTURE_ADDRESS_CLAMP;
        sd.ComparisonFunc = D3D11_COMPARISON_NEVER;
        sd.MaxLOD         = D3D11_FLOAT32_MAX;
        m_dev->CreateSamplerState(&sd, &m_fontSmp);
    }

    // --- blend (alpha blend, over) ---
    {
        D3D11_BLEND_DESC bd{};
        bd.RenderTarget[0].BlendEnable           = TRUE;
        bd.RenderTarget[0].SrcBlend              = D3D11_BLEND_SRC_ALPHA;
        bd.RenderTarget[0].DestBlend             = D3D11_BLEND_INV_SRC_ALPHA;
        bd.RenderTarget[0].BlendOp               = D3D11_BLEND_OP_ADD;
        bd.RenderTarget[0].SrcBlendAlpha         = D3D11_BLEND_ONE;
        bd.RenderTarget[0].DestBlendAlpha        = D3D11_BLEND_INV_SRC_ALPHA;
        bd.RenderTarget[0].BlendOpAlpha          = D3D11_BLEND_OP_ADD;
        bd.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
        m_dev->CreateBlendState(&bd, &m_blend);
    }

    // --- rasteriser ---
    {
        D3D11_RASTERIZER_DESC rd{};
        rd.FillMode = D3D11_FILL_SOLID;
        rd.CullMode = D3D11_CULL_NONE;
        m_dev->CreateRasterizerState(&rd, &m_rast);
    }

    // --- depth-stencil (no depth test for 2-D overlay) ---
    {
        D3D11_DEPTH_STENCIL_DESC dsd{};
        dsd.DepthEnable    = FALSE;
        dsd.StencilEnable  = FALSE;
        m_dev->CreateDepthStencilState(&dsd, &m_dss);
    }

    m_verts.reserve(kMaxVerts);
    return true;
}

void DebugOverlay::beginFrame()
{
    m_verts.clear();
    const float clear[4] = {0.0f, 0.0f, 0.0f, 0.4f};
    m_ctx->ClearRenderTargetView(m_rtv, clear);
}

void DebugOverlay::pushGlyph(float px, float py, uint8_t ch,
                              float r, float g, float b, float a)
{
    if (ch >= 128) ch = '?';
    if (m_verts.size() + 6 > kMaxVerts) flushVB();

    constexpr float invW = 1.0f / (128.0f * 8.0f);
    constexpr float invH = 1.0f / 8.0f;

    float u0 = static_cast<float>(ch) * 8.0f * invW;
    float u1 = u0 + 8.0f * invW;
    float v0 = 0.0f;
    float v1 = 1.0f;

    float x0 = px,       y0 = py;
    float x1 = px + 8.f, y1 = py + 8.f;

    // two triangles (CCW)
    m_verts.push_back({x0,y0, u0,v0, r,g,b,a});
    m_verts.push_back({x1,y0, u1,v0, r,g,b,a});
    m_verts.push_back({x0,y1, u0,v1, r,g,b,a});

    m_verts.push_back({x1,y0, u1,v0, r,g,b,a});
    m_verts.push_back({x1,y1, u1,v1, r,g,b,a});
    m_verts.push_back({x0,y1, u0,v1, r,g,b,a});
}

void DebugOverlay::drawText(float px, float py, const char* text,
                            float r, float g, float b, float a)
{
    for (const char* p = text; *p; ++p, px += 9.0f)
        pushGlyph(px, py, static_cast<uint8_t>(*p), r, g, b, a);
}

void DebugOverlay::drawEntityMarker(float px, float py,
                                    float r, float g, float b)
{
    // 3-pixel cross-hair drawn as font glyphs (+)
    // centred at (px, py) in screen space
    float x = px - 4.0f;
    float y = py - 4.0f;
    pushGlyph(x, y, '+', r, g, b, 1.0f);
}

void DebugOverlay::flushVB()
{
    if (m_verts.empty()) return;

    // upload vertices
    D3D11_MAPPED_SUBRESOURCE ms{};
    if (SUCCEEDED(m_ctx->Map(m_vb, 0, D3D11_MAP_WRITE_DISCARD, 0, &ms)))
    {
        const size_t bytes = sizeof(Vertex2D) * m_verts.size();
        memcpy(ms.pData, m_verts.data(), bytes);
        m_ctx->Unmap(m_vb, 0);
    }

    // update constant buffer
    D3D11_MAPPED_SUBRESOURCE cms{};
    if (SUCCEEDED(m_ctx->Map(m_cb, 0, D3D11_MAP_WRITE_DISCARD, 0, &cms)))
    {
        CBOverlay cb{};
        cb.screenW = static_cast<float>(m_width);
        cb.screenH = static_cast<float>(m_height);
        memcpy(cms.pData, &cb, sizeof(cb));
        m_ctx->Unmap(m_cb, 0);
    }

    // set state
    m_ctx->OMSetRenderTargets(1, &m_rtv, nullptr);
    m_ctx->OMSetBlendState(m_blend, nullptr, 0xFFFFFFFF);
    m_ctx->OMSetDepthStencilState(m_dss, 0);
    m_ctx->RSSetState(m_rast);

    D3D11_VIEWPORT vp{};
    vp.Width    = static_cast<float>(m_width);
    vp.Height   = static_cast<float>(m_height);
    vp.MaxDepth = 1.0f;
    m_ctx->RSSetViewports(1, &vp);

    m_ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    UINT stride = sizeof(Vertex2D), offset = 0;
    m_ctx->IASetVertexBuffers(0, 1, &m_vb, &stride, &offset);
    m_ctx->IASetInputLayout(m_il);
    m_ctx->VSSetShader(m_vs, nullptr, 0);
    m_ctx->VSSetConstantBuffers(0, 1, &m_cb);
    m_ctx->PSSetShader(m_ps, nullptr, 0);
    m_ctx->PSSetShaderResources(0, 1, &m_fontSrv);
    m_ctx->PSSetSamplers(0, 1, &m_fontSmp);

    m_ctx->Draw(static_cast<UINT>(m_verts.size()), 0);
    m_verts.clear();
}

void DebugOverlay::endFrame()
{
    flushVB();
    m_sc->Present(1, 0);
}

void DebugOverlay::destroy()
{
#define SAFE_RELEASE(p) do { if (p) { (p)->Release(); (p) = nullptr; } } while(0)
    SAFE_RELEASE(m_dss);
    SAFE_RELEASE(m_rast);
    SAFE_RELEASE(m_blend);
    SAFE_RELEASE(m_fontSmp);
    SAFE_RELEASE(m_fontSrv);
    SAFE_RELEASE(m_fontTex);
    SAFE_RELEASE(m_ps);
    SAFE_RELEASE(m_vs);
    SAFE_RELEASE(m_il);
    SAFE_RELEASE(m_cb);
    SAFE_RELEASE(m_vb);
    SAFE_RELEASE(m_rtv);
    SAFE_RELEASE(m_sc);
    SAFE_RELEASE(m_ctx);
    SAFE_RELEASE(m_dev);
#undef SAFE_RELEASE
}

// ---------------------------------------------------------------------------
// World-to-screen projection (simple orthographic debug projection)
// In a real harness, extract the view-projection matrix from the game.
// ---------------------------------------------------------------------------
static bool worldToScreen(float wx, float wy, float wz,
                           UINT screenW, UINT screenH,
                           float& outX, float& outY)
{
    // Trivial top-down orthographic: map X/Z world to screen, discard Y
    // Scale factor and origin are adjustable at runtime.
    static constexpr float kScale  = 4.0f;   // pixels per world unit
    static constexpr float kOriginX = 0.0f;
    static constexpr float kOriginZ = 0.0f;

    outX = screenW * 0.5f + (wx - kOriginX) * kScale;
    outY = screenH * 0.5f + (wz - kOriginZ) * kScale;
    (void)wy;

    // cull if outside padded viewport
    return outX > -32.f && outX < screenW + 32.f &&
           outY > -32.f && outY < screenH + 32.f;
}

// ---------------------------------------------------------------------------
// Window procedure
// ---------------------------------------------------------------------------
static LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp)
{
    if (msg == WM_DESTROY) { PostQuitMessage(0); return 0; }
    if (msg == WM_KEYDOWN && wp == VK_ESCAPE) { DestroyWindow(hwnd); return 0; }
    return DefWindowProcW(hwnd, msg, wp, lp);
}

// ---------------------------------------------------------------------------
// Render one frame of entity data
// ---------------------------------------------------------------------------
static void renderFrame(DebugOverlay& overlay,
                        const std::vector<EntityRecord>& entities)
{
    overlay.beginFrame();

    const UINT W = overlay.width();
    const UINT H = overlay.height();

    overlay.drawText(4.0f, 4.0f, "ANTI-CHEAT DEBUG OVERLAY  [ESC] quit",
                     0.9f, 0.9f, 0.1f);

    char buf[128];
    wsprintfA(buf, "Entities: %d", static_cast<int>(entities.size()));
    overlay.drawText(4.0f, 16.0f, buf, 0.8f, 0.8f, 0.8f);

    for (size_t i = 0; i < entities.size(); ++i)
    {
        const EntityRecord& e = entities[i];
        if (!e.alive) continue;

        float sx = 0.f, sy = 0.f;
        if (!worldToScreen(e.x, e.y, e.z, W, H, sx, sy))
            continue;

        // colour by team
        float cr = 0.2f, cg = 1.0f, cb = 0.2f; // green  = player
        if (e.team == 1) { cr = 1.0f; cg = 0.2f; cb = 0.2f; } // red = enemy
        if (e.team == 2) { cr = 0.9f; cg = 0.9f; cb = 0.2f; } // yellow = neutral

        overlay.drawEntityMarker(sx, sy, cr, cg, cb);

        // label: index + health
        wsprintfA(buf, "#%d hp%.0f", static_cast<int>(i), static_cast<double>(e.health));
        overlay.drawText(sx + 6.0f, sy - 10.0f, buf, cr, cg, cb);
    }

    overlay.endFrame();
}

