/*
 * kmem.c - Windows kernel driver: map a user buffer and service
 *          read/write requests for a caller-chosen virtual address range.
 *
 * Build (WDK, x64 free build):
 *   cl /kernel /W4 /WX /O2 /GS- /Gz /D_WIN64 /DNDEBUG \
 *      /I"%WDK_INC%\km" kmem.c \
 *      /link /NODEFAULTLIB /DRIVER /SUBSYSTEM:NATIVE \
 *      /ENTRY:DriverEntry /OUT:kmem.sys \
 *      ntoskrnl.lib wdm.lib
 *
 * Exported device interface  \\.\KMem
 * IOCTL_KMEM_MAP_BUFFER  - register caller's user buffer + VA range
 * IOCTL_KMEM_READ        - read from the registered VA range
 * IOCTL_KMEM_WRITE       - write to  the registered VA range
 * IOCTL_KMEM_UNMAP_BUFFER- release the mapping
 */

#include <wdm.h>

/* -----------------------------------------------------------------------
 * IOCTL codes
 * ----------------------------------------------------------------------- */
#define KMEM_DEVICE_TYPE    0x8001ul

#define IOCTL_KMEM_MAP_BUFFER \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_READ \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_UNMAP_BUFFER \
    CTL_CODE(KMEM_DEVICE_TYPE, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* -----------------------------------------------------------------------
 * IOCTL input / output structures (packed, copied via METHOD_BUFFERED)
 * ----------------------------------------------------------------------- */

/* IOCTL_KMEM_MAP_BUFFER – in */
typedef struct _KMEM_MAP_INPUT {
    ULONG_PTR UserBuffer;   /* user-mode VA of the data buffer           */
    SIZE_T    BufferLength; /* byte length of that buffer                */
    ULONG_PTR RangeBase;   /* first VA the caller wants to cover        */
    SIZE_T    RangeLength;  /* length of the VA range                    */
} KMEM_MAP_INPUT, *PKMEM_MAP_INPUT;

/* IOCTL_KMEM_READ – in */
typedef struct _KMEM_RW_INPUT {
    ULONG_PTR Address; /* virtual address to read from / write to       */
    SIZE_T    Length;  /* byte count                                     */
} KMEM_RW_INPUT, *PKMEM_RW_INPUT;

/* IOCTL_KMEM_READ – out: raw bytes follow in the system buffer          */
/* IOCTL_KMEM_WRITE – in: KMEM_RW_INPUT header, then raw bytes           */

/* -----------------------------------------------------------------------
 * Per-handle (file-object) context
 * ----------------------------------------------------------------------- */
typedef struct _KMEM_CONTEXT {
    FAST_MUTEX    Lock;
    PMDL          Mdl;           /* MDL locking the user buffer          */
    PVOID         MappedVa;      /* kernel VA of the locked pages        */
    ULONG_PTR     RangeBase;     /* caller-chosen VA range start         */
    SIZE_T        RangeLength;   /* caller-chosen VA range length        */
    SIZE_T        BufferLength;  /* length of the locked user buffer     */
} KMEM_CONTEXT, *PKMEM_CONTEXT;

/* -----------------------------------------------------------------------
 * Globals
 * ----------------------------------------------------------------------- */
static PDEVICE_OBJECT  g_DeviceObject;
static UNICODE_STRING  g_DeviceName;
static UNICODE_STRING  g_SymlinkName;

/* -----------------------------------------------------------------------
 * Forward declarations
 * ----------------------------------------------------------------------- */
DRIVER_UNLOAD         KmemUnload;
DRIVER_DISPATCH       KmemCreate;
DRIVER_DISPATCH       KmemCleanup;
DRIVER_DISPATCH       KmemClose;
DRIVER_DISPATCH       KmemDeviceControl;

static NTSTATUS KmemMapBuffer(PKMEM_CONTEXT Ctx,
                              PKMEM_MAP_INPUT In,
                              PEPROCESS Process);
static VOID     KmemUnmapBuffer(PKMEM_CONTEXT Ctx);
static NTSTATUS KmemRead(PKMEM_CONTEXT Ctx,
                         PKMEM_RW_INPUT Rw,
                         PVOID OutBuf,
                         SIZE_T OutLen,
                         PULONG_PTR Written);
static NTSTATUS KmemWrite(PKMEM_CONTEXT Ctx,
                          PKMEM_RW_INPUT Rw,
                          PVOID DataBuf,
                          SIZE_T DataLen);

/* -----------------------------------------------------------------------
 * DriverEntry
 * ----------------------------------------------------------------------- */
NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath)
{
    NTSTATUS status;

    UNREFERENCED_PARAMETER(RegistryPath);

    RtlInitUnicodeString(&g_DeviceName,  L"\\Device\\KMem");
    RtlInitUnicodeString(&g_SymlinkName, L"\\DosDevices\\KMem");

    status = IoCreateDevice(DriverObject,
                            0,
                            &g_DeviceName,
                            KMEM_DEVICE_TYPE,
                            FILE_DEVICE_SECURE_OPEN,
                            FALSE,
                            &g_DeviceObject);
    if (!NT_SUCCESS(status))
        return status;

    status = IoCreateSymbolicLink(&g_SymlinkName, &g_DeviceName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(g_DeviceObject);
        return status;
    }

    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KmemCreate;
    DriverObject->MajorFunction[IRP_MJ_CLEANUP]        = KmemCleanup;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KmemClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KmemDeviceControl;
    DriverObject->DriverUnload                          = KmemUnload;

    g_DeviceObject->Flags &= ~DO_DEVICE_INITIALIZING;
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemUnload
 * ----------------------------------------------------------------------- */
VOID
KmemUnload(
    _In_ PDRIVER_OBJECT DriverObject)
{
    UNREFERENCED_PARAMETER(DriverObject);
    IoDeleteSymbolicLink(&g_SymlinkName);
    IoDeleteDevice(g_DeviceObject);
}

/* -----------------------------------------------------------------------
 * IRP_MJ_CREATE – allocate per-handle context
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemCreate(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp)
{
    PIO_STACK_LOCATION isl = IoGetCurrentIrpStackLocation(Irp);
    PKMEM_CONTEXT      ctx;

    UNREFERENCED_PARAMETER(DeviceObject);

    ctx = (PKMEM_CONTEXT)ExAllocatePoolWithTag(NonPagedPoolNx,
                                               sizeof(KMEM_CONTEXT),
                                               'meKD');
    if (!ctx) {
        Irp->IoStatus.Status = STATUS_INSUFFICIENT_RESOURCES;
        IoCompleteRequest(Irp, IO_NO_INCREMENT);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    RtlZeroMemory(ctx, sizeof(KMEM_CONTEXT));
    ExInitializeFastMutex(&ctx->Lock);

    isl->FileObject->FsContext = ctx;

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * IRP_MJ_CLEANUP – release MDL / mapping while handles still open
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemCleanup(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp)
{
    PIO_STACK_LOCATION isl = IoGetCurrentIrpStackLocation(Irp);
    PKMEM_CONTEXT      ctx = (PKMEM_CONTEXT)isl->FileObject->FsContext;

    UNREFERENCED_PARAMETER(DeviceObject);

    if (ctx) {
        ExAcquireFastMutex(&ctx->Lock);
        KmemUnmapBuffer(ctx);
        ExReleaseFastMutex(&ctx->Lock);
    }

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * IRP_MJ_CLOSE – free context
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp)
{
    PIO_STACK_LOCATION isl = IoGetCurrentIrpStackLocation(Irp);
    PKMEM_CONTEXT      ctx = (PKMEM_CONTEXT)isl->FileObject->FsContext;

    UNREFERENCED_PARAMETER(DeviceObject);

    if (ctx) {
        /* Cleanup already ran; just free the pool block. */
        ExFreePoolWithTag(ctx, 'meKD');
        isl->FileObject->FsContext = NULL;
    }

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * IRP_MJ_DEVICE_CONTROL
 * ----------------------------------------------------------------------- */
NTSTATUS
KmemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _Inout_ PIRP Irp)
{
    PIO_STACK_LOCATION isl    = IoGetCurrentIrpStackLocation(Irp);
    PKMEM_CONTEXT      ctx    = (PKMEM_CONTEXT)isl->FileObject->FsContext;
    ULONG              code   = isl->Parameters.DeviceIoControl.IoControlCode;
    ULONG              inLen  = isl->Parameters.DeviceIoControl.InputBufferLength;
    ULONG              outLen = isl->Parameters.DeviceIoControl.OutputBufferLength;
    PVOID              sysBuf = Irp->AssociatedIrp.SystemBuffer;
    NTSTATUS           status = STATUS_INVALID_DEVICE_REQUEST;
    ULONG_PTR          info   = 0;

    UNREFERENCED_PARAMETER(DeviceObject);

    if (!ctx) {
        status = STATUS_INVALID_HANDLE;
        goto done;
    }

    switch (code) {

    /* ------------------------------------------------------------------
     * MAP: lock the user buffer and record the VA range.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_MAP_BUFFER: {
        if (inLen < sizeof(KMEM_MAP_INPUT)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        KMEM_MAP_INPUT in;
        RtlCopyMemory(&in, sysBuf, sizeof(in));

        if (in.BufferLength == 0 || in.RangeLength == 0) {
            status = STATUS_INVALID_PARAMETER;
            break;
        }

        ExAcquireFastMutex(&ctx->Lock);

        if (ctx->Mdl) {
            /* Already mapped; caller must unmap first. */
            status = STATUS_DEVICE_ALREADY_ATTACHED;
        } else {
            status = KmemMapBuffer(ctx, &in, IoGetCurrentProcess());
        }

        ExReleaseFastMutex(&ctx->Lock);
        break;
    }

    /* ------------------------------------------------------------------
     * READ: copy bytes from the mapped region into the output buffer.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ: {
        if (inLen < sizeof(KMEM_RW_INPUT)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        KMEM_RW_INPUT rw;
        RtlCopyMemory(&rw, sysBuf, sizeof(rw));

        ExAcquireFastMutex(&ctx->Lock);
        status = KmemRead(ctx, &rw, sysBuf, (SIZE_T)outLen, &info);
        ExReleaseFastMutex(&ctx->Lock);
        break;
    }

    /* ------------------------------------------------------------------
     * WRITE: copy bytes from the input buffer into the mapped region.
     * The input layout is: KMEM_RW_INPUT header + data bytes.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE: {
        if (inLen < sizeof(KMEM_RW_INPUT)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }
        KMEM_RW_INPUT rw;
        RtlCopyMemory(&rw, sysBuf, sizeof(rw));

        SIZE_T dataLen = (SIZE_T)inLen - sizeof(KMEM_RW_INPUT);
        PVOID  dataBuf = (PUCHAR)sysBuf + sizeof(KMEM_RW_INPUT);

        ExAcquireFastMutex(&ctx->Lock);
        status = KmemWrite(ctx, &rw, dataBuf, dataLen);
        ExReleaseFastMutex(&ctx->Lock);
        break;
    }

    /* ------------------------------------------------------------------
     * UNMAP: release the MDL and kernel mapping.
     * ------------------------------------------------------------------ */
    case IOCTL_KMEM_UNMAP_BUFFER: {
        ExAcquireFastMutex(&ctx->Lock);
        KmemUnmapBuffer(ctx);
        ExReleaseFastMutex(&ctx->Lock);
        status = STATUS_SUCCESS;
        break;
    }

    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

done:
    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* -----------------------------------------------------------------------
 * KmemMapBuffer
 *   Lock the caller's user buffer into memory and create a kernel mapping.
 *   Must be called with ctx->Lock held.
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemMapBuffer(
    _Inout_ PKMEM_CONTEXT   Ctx,
    _In_    PKMEM_MAP_INPUT  In,
    _In_    PEPROCESS        Process)
{
    PMDL  mdl;
    PVOID mapped;

    UNREFERENCED_PARAMETER(Process);

    /*
     * Probe and lock the user pages.  IoAllocateMdl references the
     * calling process's address space.  We require the buffer to be
     * accessible from user mode; KernelMode probing would skip that check.
     */
    mdl = IoAllocateMdl((PVOID)In->UserBuffer,
                        (ULONG)In->BufferLength,
                        FALSE,
                        FALSE,
                        NULL);
    if (!mdl)
        return STATUS_INSUFFICIENT_RESOURCES;

    __try {
        MmProbeAndLockPages(mdl, UserMode, IoReadAccess);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return GetExceptionCode();
    }

    /* Create a kernel-mode mapping with no caching override. */
    mapped = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority |
                                               MdlMappingNoExecute);
    if (!mapped) {
        MmUnlockPages(mdl);
        IoFreeMdl(mdl);
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    Ctx->Mdl          = mdl;
    Ctx->MappedVa     = mapped;
    Ctx->RangeBase    = In->RangeBase;
    Ctx->RangeLength  = In->RangeLength;
    Ctx->BufferLength = In->BufferLength;

    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemUnmapBuffer
 *   Tear down the MDL mapping.  Safe to call when nothing is mapped.
 *   Must be called with ctx->Lock held.
 * ----------------------------------------------------------------------- */
static VOID
KmemUnmapBuffer(
    _Inout_ PKMEM_CONTEXT Ctx)
{
    if (!Ctx->Mdl)
        return;

    MmUnmapLockedPages(Ctx->MappedVa, Ctx->Mdl);
    MmUnlockPages(Ctx->Mdl);
    IoFreeMdl(Ctx->Mdl);

    Ctx->Mdl          = NULL;
    Ctx->MappedVa     = NULL;
    Ctx->RangeBase    = 0;
    Ctx->RangeLength  = 0;
    Ctx->BufferLength = 0;
}

/* -----------------------------------------------------------------------
 * RangeToBuffer
 *   Translate an arbitrary [Address, Address+Length) within the registered
 *   VA range to an offset into the locked buffer, checking all bounds.
 *
 *   Returns STATUS_SUCCESS and sets *Offset on success.
 * ----------------------------------------------------------------------- */
static NTSTATUS
RangeToBuffer(
    _In_  PKMEM_CONTEXT Ctx,
    _In_  ULONG_PTR     Address,
    _In_  SIZE_T        Length,
    _Out_ SIZE_T       *Offset)
{
    ULONG_PTR rangeEnd, reqEnd;

    if (!Ctx->Mdl)
        return STATUS_INVALID_DEVICE_STATE;

    if (Length == 0)
        return STATUS_INVALID_PARAMETER;

    /* Overflow guards */
    if (Address < Ctx->RangeBase)
        return STATUS_ACCESS_VIOLATION;

    *Offset = Address - Ctx->RangeBase;

    /* Check that [Address, Address+Length) stays within [RangeBase, RangeBase+RangeLength) */
    if (Ctx->RangeLength < Length || *Offset > Ctx->RangeLength - Length)
        return STATUS_ACCESS_VIOLATION;

    rangeEnd = Ctx->RangeBase + Ctx->RangeLength; /* one-past-end of VA range  */
    reqEnd   = Address + Length;
    if (reqEnd > rangeEnd || reqEnd < Address)   /* overflow / out of range   */
        return STATUS_ACCESS_VIOLATION;

    /* Check that the offset fits within the locked buffer */
    if (*Offset >= Ctx->BufferLength ||
        Length   > Ctx->BufferLength - *Offset)
        return STATUS_ACCESS_VIOLATION;

    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemRead
 *   Copy bytes from the mapped buffer at the requested VA into OutBuf.
 *   Must be called with ctx->Lock held.
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemRead(
    _In_    PKMEM_CONTEXT   Ctx,
    _In_    PKMEM_RW_INPUT  Rw,
    _Out_   PVOID           OutBuf,
    _In_    SIZE_T          OutLen,
    _Out_   PULONG_PTR      Written)
{
    NTSTATUS status;
    SIZE_T   offset;

    *Written = 0;

    if (OutLen < Rw->Length)
        return STATUS_BUFFER_TOO_SMALL;

    status = RangeToBuffer(Ctx, Rw->Address, Rw->Length, &offset);
    if (!NT_SUCCESS(status))
        return status;

    RtlCopyMemory(OutBuf,
                  (PUCHAR)Ctx->MappedVa + offset,
                  Rw->Length);

    *Written = Rw->Length;
    return STATUS_SUCCESS;
}

/* -----------------------------------------------------------------------
 * KmemWrite
 *   Copy DataLen bytes from DataBuf into the mapped buffer at the
 *   requested VA.  Must be called with ctx->Lock held.
 * ----------------------------------------------------------------------- */
static NTSTATUS
KmemWrite(
    _In_ PKMEM_CONTEXT   Ctx,
    _In_ PKMEM_RW_INPUT  Rw,
    _In_ PVOID           DataBuf,
    _In_ SIZE_T          DataLen)
{
    NTSTATUS status;
    SIZE_T   offset;

    if (DataLen < Rw->Length)
        return STATUS_BUFFER_TOO_SMALL;

    status = RangeToBuffer(Ctx, Rw->Address, Rw->Length, &offset);
    if (!NT_SUCCESS(status))
        return status;

    RtlCopyMemory((PUCHAR)Ctx->MappedVa + offset,
                  DataBuf,
                  Rw->Length);

    return STATUS_SUCCESS;
}

